-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_ent211 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = 'ae97ff5e-86e3-54a5-9dfd-abe30cfa3bd7' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = 'ae97ff5e-86e3-54a5-9dfd-abe30cfa3bd7' and revision = 1;
select throws_ok($$select private.official_bank_ent211('apply')$$, 'P0001',
  'Official bank ENT211: ae97ff5e-86e3-54a5-9dfd-abe30cfa3bd7 is not the same migration-owned question',
